'use strict';
(() => {
 const D = window.TERRA;
 const R = window.ROSTER_RENDER;
 const $ = s => document.querySelector(s);
 const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const region = id => D.regions.find(x => x.id === id);
 const story = id => D.stories.find(x => x.id === id);
 const num = n => String(n).padStart(2,'0');
 let storageOK = true;
 function load(key, fallback) { try { const v=JSON.parse(localStorage.getItem('terra-'+key)); return v ?? fallback; } catch { storageOK=false; return fallback; } }
 function save(key, value) { try { localStorage.setItem('terra-'+key,JSON.stringify(value)); } catch { storageOK=false; } }
 const prefs=load('preferences',{dark:false,full:false,size:18});
 if(!Number.isFinite(prefs.size)) prefs.size=18;
 let favorites = load('favorites',[]); if(!Array.isArray(favorites)) favorites=[];
 let progress = load('progress',{}); if(!progress || typeof progress!=='object' || Array.isArray(progress)) progress={};
 let filters={q:'',area:'all',region:'all',saved:false};
 let current={view:'home',id:null};
 let lastRoute='';
 let isRestoring=false;let progressSavedAt=0;
 let searchReturnFocus=null;
 const canonical = n => ({'幼年的阿米娅':'阿米娅','百炼嘉维尔':'嘉维尔'}[n] || n);
 const persons=[];
 for(const s of D.stories) for(const p of s.people) {
  const key=canonical(p[0]);
  let found=persons.find(x=>x.name===key);
  if(found){found.stories.push(s.id);found.entries.push(p);continue;}
  persons.push({id:'p'+persons.length,name:key,role:p[1],bio:p[2],region:s.region,stories:[s.id],entries:[p]});
 }
 const getPerson = name => persons.find(x => x.name===canonical(name));
 const words = s => (s.intro+s.sections.flat().join('')+(s.origins?.periods.map(p=>p.body).join('')||'')).replace(/\s/g,'').length;
 const readTime = s => Math.max(2,Math.ceil(words(s)/300));
 function applyPrefs(){document.body.classList.toggle('dark',!!prefs.dark);document.documentElement.style.setProperty('--reading-size',prefs.size+'px');save('preferences',prefs);}
 applyPrefs();
 function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2200);}
 function motif(seed=0,hero=false){
  const paths=[];
  for(let i=0;i<27;i++){
   let pts=[];for(let j=0;j<=130;j++){const a=j/130*Math.PI*2;const r=63+i*7.4;const ripple=1+.1*Math.sin(a*3+seed)+.065*Math.cos(a*5+i*.04)+.03*Math.sin(a*9);pts.push([(340+Math.cos(a)*r*ripple).toFixed(1),(285+Math.sin(a)*r*ripple*.87).toFixed(1)]);}
   paths.push(`<path d="M${pts.map(p=>p.join(',')).join('L')}Z"/>`);
  }
  return `<svg viewBox="0 0 650 600" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><pattern id="grid-${seed}" width="42" height="42" patternUnits="userSpaceOnUse"><path d="M42 0H0V42" stroke="currentColor" stroke-width=".3"/></pattern><linearGradient id="fade-${seed}"><stop stop-color="white" stop-opacity="0"/><stop offset=".22" stop-color="white"/><stop offset="1" stop-color="white"/></linearGradient><mask id="mask-${seed}"><rect width="650" height="600" fill="url(#fade-${seed})"/></mask></defs><g mask="url(#mask-${seed})"><rect x="45" y="25" width="560" height="525" fill="url(#grid-${seed})" color="#7e9882" opacity=".25"/><g stroke="#698471" stroke-width=".7" opacity=".38">${paths.join('')}</g><circle cx="340" cy="285" r="230" stroke="#789080" stroke-width=".7" stroke-dasharray="2 7"/><path d="M92 420Q185 375 244 303T369 247T492 163" stroke="#b28b53" stroke-width="1.6" stroke-dasharray="4 6"/><g fill="#b28b53"><circle cx="125" cy="402" r="4"/><circle cx="249" cy="295" r="4"/><circle cx="375" cy="243" r="4"/><circle cx="492" cy="163" r="4"/></g><g stroke="#a88b5e" stroke-width="1"><path d="M520 68v54m-27-27h54m-27-22 8 22-8-5-8 5z"/><circle cx="520" cy="95" r="18"/></g><g fill="#6c806f" font-family="Georgia,serif" font-size="9" letter-spacing="2"><text x="517" y="57">N</text><text x="144" y="397">THE JOURNEY</text><text x="388" y="230">TERRA</text><text x="100" y="531">A LAND OF MANY STORIES</text></g><g transform="translate(250 360)" stroke="#496b5c" stroke-width="1.1"><path fill="#e5e7d9" d="M0 64V33l30-12 23 10V0l25-8 22 10v26l38-8 23 14v27l21 10-12 13H27Z"/><path d="m0 33 30 14 23-16m-23-10v40m23-61 25 12 22-10m-22-10v69m22-33 38 20 23-12m-23-14v53M0 64l27 20m0-23v23l51-14 60 3 32 11M59 18l12 5m-12 5 12 5m13-15 10-3m-10 15 10-3M6 45l15 7m-15 3 15 7m90-20 17 7m-17 3 17 7"/><path d="m-14 94 60 6 77-10 64 8" opacity=".4"/></g>${hero?'<g stroke="#b28b53" opacity=".6"><path d="M70 45h18m-9-9v18M564 520h18m-9-9v18"/></g>':''}</g></svg>`;
 }
 function artwork(type){
  const base='<rect width="500" height="230" fill="#e3e7db"/><path d="M0 190H500M0 197H500" stroke="#779281" stroke-width=".7" opacity=".4"/>';
  const visuals={stars:'<g stroke="#547566" fill="none"><circle cx="300" cy="104" r="62"/><ellipse cx="300" cy="104" rx="110" ry="26" transform="rotate(-28 300 104)"/><circle cx="300" cy="104" r="90" stroke-dasharray="1 7"/><path d="m70 190 60-80 48 80m-72-15 44-1m-26-48 13 64M393 190V92l21-12 20 12v98m-41-82h41m-41 21h41m-41 21h41"/><path d="M334 45 354 14" stroke="#ad8752" stroke-width="2"/><circle cx="354" cy="14" r="3" fill="#ad8752"/></g><path d="M0 214q95-42 174-17t184-6 142 2" stroke="#779281" fill="none"/>',light:'<g fill="none" stroke="#527160"><path d="M8 199q84-33 153-13t151 0 188-4M8 212q84-33 153-13t151 0 188-4M350 184 365 55h24l16 129M354 153h46M360 107h35M361 55V37h33v18M357 37h40l-20-17z"/><path d="m365 57-185 59 6-38 179-21m24 0 111 26" stroke="#ad8752" stroke-width="1"/><circle cx="118" cy="56" r="21" stroke="#ad8752"/></g><path d="m41 191 36-64 32 64m100-2 40-100 51 102m-81-66 29 8 14-14" stroke="#6d8b72" fill="none"/>',mountain:'<g stroke="#65836c" fill="none"><path d="m0 188 87-110 65 73 71-123 95 137 58-84 124 120M0 210l88-90 65 65 70-116 95 122 58-75 124 103M201 61l22 29 20-30M63 107l24 26 25-26"/><path d="m48 209 119-9 99 19 131-16 86 8"/><circle cx="394" cy="42" r="23" stroke="#b28b53"/><path d="m342 159 2-27h35l3 27m-49-27h55l-27-19zM350 159v-16h16v16" stroke="#496c56"/></g>'};
  return `<svg viewBox="0 0 500 230" preserveAspectRatio="xMidYMid slice" aria-hidden="true">${base}${visuals[type]||visuals.mountain}</svg>`;
 }
 function pageHeading(kicker,title,desc,mark){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="page-mark" aria-hidden="true">${mark}</div></div>`;}
 function featureCard(id,type){const s=story(id),r=region(s.region);return `<a href="#/story/${s.id}" class="feature-card"><div class="art-box">${artwork(type)}<span class="art-number">FIELD NOTES / ${num(s.order)}</span></div><div class="feature-copy"><div class="meta">${r.name}<i></i>${r.theme}</div><h3>${s.title}</h3><p>${prefs.full?s.intro:region(s.region).deck}</p><div class="card-bottom"><span>${s.subtitle}</span><span>翻开此篇 ↗</span></div></div></a>`;}
 function catalogueRow(s){const r=region(s.region);const p=progress[s.id];return `<a href="#/story/${s.id}" class="catalogue-row" style="--r:${r.color}"><div class="row-glyph" aria-hidden="true">${r.glyph}</div><div><div class="meta">${r.name}<i></i>${s.label}${p?.done?'<i></i>已读':p?.ratio>.04?'<i></i>读至 '+Math.round(p.ratio*100)+'%':''}${favorites.includes(s.id)?'<i></i>已收藏':''}</div><h3>${s.title}</h3><p>${s.subtitle}</p><div class="muted small">约 ${readTime(s)} 分钟 · ${s.groups.map(g=>window.CHAPTER_INDEX?.[g]?.title).filter(Boolean).join(' / ')||'干员档案'}</div></div><span class="row-arrow" aria-hidden="true">↗</span></a>`;}
 function home(){
  const last=Object.entries(progress).filter(([id,p])=>story(id)&&!p.done).sort((a,b)=>(b[1].at||0)-(a[1].at||0))[0];
  return `<div class="wrap"><section class="hero"><div class="hero-copy"><div class="eyebrow">ARKNIGHTS · A STORY ANTHOLOGY</div><h1>泰拉地区纪事<br><em>人物经历汇编</em></h1><p class="hero-desc">越过雪山、城邦与无垠的海。<br>沿着一个个名字，读懂他们的故乡、选择与未完的旅程。</p><div class="hero-actions"><a class="primary" href="#/story/${last?last[0]:'the-ship'}">${last?'继续上次阅读':'从卷首读起'}<span>→</span></a><a class="link-arrow" href="#/map">展开互动行纪图 <span>↗</span></a></div><p class="hero-note">非官方故事集 · 原创叙事梳理 · 含剧情剧透</p></div><div class="hero-art anniversary-art" role="img" aria-label="明日方舟官方四周年纪念图：凯尔希、阿米娅与博士"></div><div class="hero-stamp">以大地为卷　以众生为纪</div></section><div class="stats-band"><div class="stats"><div class="stat"><strong>${num(D.regions.length)}</strong><span>地区与组织</span></div><div class="stat"><strong>${num(D.stories.length)}</strong><span>篇故事</span></div><div class="stat"><strong>${window.PERSON_BIOGRAPHIES.meta.operatorPeople}</strong><span>干员人物纪事</span></div></div><div class="edition-note"><i></i>大地与众生 · 选篇第一卷</div></div><section class="section"><div class="section-head"><div><div class="eyebrow">SELECTED STORIES</div><h2>从一段故事，走进泰拉</h2><p>按地区、事件与人物查阅剧情记录。</p></div><a class="link-arrow" href="#/atlas">全部篇章 <span>↗</span></a></div><div class="featured-grid">${featureCard('columbia-stars','stars')}${featureCard('iberia-lighthouse','light')}${featureCard('yan-human-world','mountain')}</div><div class="editor-note"><div class="large-symbol" aria-hidden="true">序</div><div><h3>地区事件与人物经历的关联记录</h3><p>以游戏剧情为骨架，以地区为经，以人物为纬。讲述他们身处何地、为何选择，以及那些选择留下了什么。<br>章节附剧情图册与原文出处；主题解读另作标注。</p></div><a class="link-arrow" href="#/sources">了解编写方式 <span>↗</span></a></div></section></div><section class="section soft"><div class="wrap"><div class="section-head"><div><div class="eyebrow">LANDS & HOMELANDS</div><h2>大地辽阔，各有来处</h2></div><a class="link-arrow" href="#/atlas">查看全部 ${D.regions.length} 处 <span>↗</span></a></div><div class="region-mini-grid">${D.regions.slice(0,12).map(r=>`<a class="region-tile" href="#/atlas/${r.id}" style="--r:${r.color}"><span class="glyph" aria-hidden="true">${r.glyph}</span><strong>${r.name}</strong><small>${r.en}</small></a>`).join('')}</div></div></section><div class="wrap"><section class="route-strip"><div><div class="eyebrow">A PATH TO BEGIN</div><h2>还不知道从哪里开始？</h2><p>从一艘船出发，认识城市、幸存者与他们仍然珍视的生活。</p><a class="link-arrow" href="#/routes">选择你的阅读路线 <span>→</span></a></div><div class="route-trail">${D.routes[0].ids.slice(0,3).map((id,i)=>`<a class="trail-stop" href="#/story/${id}"><small>0${i+1} /</small><strong>${region(story(id).region).name}</strong><span>${story(id).subtitle}</span></a>`).join('')}</div></section></div>`;
 }
 function filterToolbar(view){return `<div class="toolbar"><label class="search-inline"><input id="filter-query" type="search" value="${esc(filters.q)}" placeholder="${view==='people'?'寻找人物、身份与故事…':'搜索地区、人物、篇名…'}" aria-label="筛选${view==='people'?'人物':'篇章'}"></label><select id="filter-region" aria-label="按地区筛选"><option value="all">全部地区与组织</option>${D.regions.map(r=>`<option value="${r.id}" ${filters.region===r.id?'selected':''}>${r.name}</option>`).join('')}</select><span class="result-count" id="result-count"></span></div>`;}
 function matchesText(s,q){const r=region(s.region);return [s.title,s.subtitle,s.intro,s.scope,s.sections.flat().join(''),(s.origins?.periods.map(p=>p.title+' '+p.body).join(' ')||''),s.people.flat().join(''),r.name,r.theme,s.groups.map(g=>window.CHAPTER_INDEX?.[g]?.title).join('')].join(' ').toLowerCase().includes(q.toLowerCase());}
 function filteredStories(){return D.stories.filter(s=>(filters.region==='all'||s.region===filters.region)&&(filters.area==='all'||region(s.region).area===filters.area)&&(!filters.q||matchesText(s,filters.q)));}
 function atlas(){const r=region(filters.region);return `<div class="wrap">${pageHeading('THE LANDS','大地诸境','从地区走进故事。这里按主题整理国家、城邦、聚居地与组织；它们并非同一级别的行政单位。','境')}${filterToolbar('atlas')}<div class="filter-chips" role="group" aria-label="按主题分组">${['all',...new Set(D.regions.map(r=>r.area))].map(a=>`<button class="chip ${filters.area===a?'active':''}" data-area="${a}" aria-pressed="${filters.area===a}">${a==='all'?'全部篇章':a}</button>`).join('')}</div><div id="region-overview">${r?`<div class="region-overview"><div class="meta">${r.en} · ${r.theme}</div><h2>${r.name}</h2><p>${r.deck}</p>${window.ORIGIN_UI.overview(r,prefs.full)}</div>`:''}</div><div class="catalogue" id="catalogue-results"></div></div>`;}
 function drawCatalogue(){const list=filteredStories();$('#catalogue-results').innerHTML=list.length?list.map(catalogueRow).join(''):empty('暂时没有找到这段旅程','试试其他关键词，或回到全部篇章。','reset-filters');$('#result-count').textContent=`${list.length} 篇故事`;const r=region(filters.region);$('#region-overview').innerHTML=r?`<div class="region-overview"><div class="meta">${r.en} · ${r.theme}</div><h2>${r.name}</h2><p>${r.deck}</p>${window.ORIGIN_UI.overview(r,prefs.full)}</div>`:'';}
 function people(){return R.people(filters,prefs); }
 function drawPeople(){R.draw(filters,prefs); }
 function routes(){return `<div class="wrap">${pageHeading('READING PATHS','沿着一条线，慢慢读','不必一次记住整片大地。选择你关心的问题，让人物和地点自然相遇。以下是本卷的主题阅读顺序，不是官方完整年代轴。','途')}<div class="route-list">${D.routes.map((r,i)=>`<section class="route-card"><div class="route-index">${num(i+1)}</div><div class="route-intro"><h2>${r.title}</h2><p>${r.subtitle}</p></div><div class="route-body"><div class="route-steps">${r.ids.map((id,j)=>`<a href="#/story/${id}"><span>${num(j+1)}</span>${story(id).title}</a>`).join('')}</div><p class="route-note">${r.note}</p></div></section>`).join('')}</div></div>`;}
 function sources(){return `<div class="wrap">${pageHeading('THE EDITOR’S DESK','资料室与编写札记','让每一段讲述都有来处，也让事实与解读保留清楚的边界。','录')}<div class="sources-layout"><aside class="sources-menu"><a href="#method" data-anchor="method">如何编写</a><a href="#source-list" data-anchor="source-list">资料来源</a><a href="#coverage" data-anchor="coverage">收录范围</a></aside><div><section class="source-section" id="method"><h2>先有故事，再有解读</h2><p>本卷为《明日方舟》的非官方故事集，以自写文字整理人物处境、事件转折与主题联系。没有以同人口吻新增关键事件、虚构人物对白，或把推测写成官方结局。篇题、导语与“编者札记”均为本卷创作。</p><p>每篇读后可展开“本篇出处与延伸阅读”，查看活动名、主线章节和抽查关卡。剧情以游戏内正式文本为依据；泰拉文库与 PRTS 是第三方阅读和转录入口。官方活动公告仅用于核对作品背景，不能独立证明全部剧情细节。</p><div class="boundary-note"><p><strong>关于《大地巡旅》</strong><br>本卷已核实官方公开介绍中的内容范围，但未获得设定集全文。因此当前没有声称整合设定集的所有内容，也没有使用未经核实的页码、逐字引文或书中独占设定。设定集以世界内作者及批注构成叙事，阅读时也应留意其视角与时点。</p></div><p>地区纪事先叙最早可考的起源、建制和社会变迁，再接当代事件。历史传承、当事人回顾及未明确的年代分别标注；城市、族群和医疗组织不统一套用国家建国叙事。<a href="origin-meta.json" target="_blank" rel="noopener noreferrer">地区沿革覆盖与出处统计 ↗</a>。</p><p>默认使用低剧透导览；进入正文后可开启完整阅读。完整模式会显示人物命运与重要转折。两种模式共用同一份正文，开关保存在当前浏览器。</p></section><section class="source-section" id="source-list"><h2>资料与原作入口</h2>${D.sources.map(s=>`<article class="source-item"><div class="source-type">${s.type}</div><h3><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a></h3><p>${s.note}</p></article>`).join('')}</section><section class="source-section" id="coverage"><h2>这一卷写到了哪里</h2><p>地区部分收录 ${D.stories.length} 篇地区纪事，覆盖 ${D.regions.length} 个地区与组织；人物部分以 ${window.PERSON_BIOGRAPHIES.meta.operatorPeople} 组干员人物纪事关联 ${window.ROSTER_META.operatorCount} 个常规干员条目，并整理 ${window.ROSTER_META.npcCount} 位主要剧情 NPC 的分阶段经历。另列 ${window.ROSTER_META.supportCount} 条特殊支援单位资料。同一人物的常规与异格经历合并叙述，每条纪事包含主要阶段、关键事件、关系变化和出处说明。</p><p>整理日期为 2026 年 11 月 4 日。这个日期表示本卷整理与名录快照时间。地区纪事包含 ${window.REGIONAL_ORIGINS.meta.regions} 份地区沿革、${window.REGIONAL_ORIGINS.meta.periods} 个沿革阶段及 ${window.REGIONAL_CHRONICLES.meta.periods} 个事件与补记阶段，合计正文约 ${((window.REGIONAL_CHRONICLES.meta.characters+window.REGIONAL_ORIGINS.meta.characters)/10000).toFixed(1)} 万字符。人物纪事读取各关联形态的公开档案、晋升记录、399 段密录正文，并以主线及活动原文核对关键经历。索引已整理 1615 段主线、活动与故事集场景，出场匹配只作检索，不等于每段均在人物正文中复述。地区篇章已扩写为分阶段纪事，并与人物经历双向链接。每篇注明实际采用的作品和关卡，不把整理日期当作全部剧情的覆盖终点。塔拉与伦蒂尼姆的后续归入维多利亚，叙拉古接《揭幕者们》；雷姆必拓保留矿区生活、离乡与人物材料能够支持的范围。</p><p>主线、活动与回忆具有不同的时间层次，本卷没有强行拼成一条精确年代轴。集成战略等具有分支的内容，也没有被合并为唯一已发生的未来。</p><p>页面中的地形纹样与小幅线描为本网站绘制的阅读意象，<strong>不是官方地图、国徽、疆域或城市复原图</strong>。未收录立绘的人物使用姓名标记，不代表官方徽章。</p><h3>剧情图册与事件过程</h3><p>重点事件进一步展开各方行动、关键转折和直接结果。正文配图及各篇图册根据所引剧情脚本中的图像调用核对，当前收录 ${window.STORY_ART.meta.cg} 张剧情 CG 与剧情插图，另有 ${window.STORY_ART.meta.backgrounds} 张场景图。图注列出实际出场章节，可点击放大并回到对应事件；场景图单独标明。</p><p>图册按正文引用场景归类，不表示收齐每部活动全部画面。部分图像属于章节中的回忆或记录，不能据同场调用推定发生在同一年。<a href="story-art-meta.json" target="_blank" rel="noopener noreferrer">剧情图册收录与来源统计 ↗</a></p><h3>互动地图与官方美术</h3><p>行纪地图采用游戏原生世界底图（PRTS社区转存），保留其原有地形和迷雾；已核实的地区节点按底图布点，其他地区和移动组织单列。节点不代表城市实时位置，共有人物连线不代表道路或因果关系。人物立绘按游戏角色 ID 对应，初始与精英化立绘可切换；未核实的 NPC 图片不配用其他人物代替。</p><p>全站背景采用<a href="https://ak.hypergryph.com/special/4th-anniversary/index.html" target="_blank" rel="noopener noreferrer">鹰角官方四周年专题纪念图 ↗</a>。角色美术取自<a href="https://github.com/ArknightsAssets/ArknightsAssets2" target="_blank" rel="noopener noreferrer">社区维护的游戏美术公开镜像 ↗</a>；它不是官方运营站点。图片已作尺寸与格式优化，权利归原权利人。</p><h3>完整干员名录的口径</h3><p>本次公开中文数据镜像中，常规可获取标记的干员条目为 ${window.ROSTER_META.operatorCount} 个；包括异格、联动、机器人与活动赠送干员。“可获取”是数据口径，不表示当前仍能抽取或兑换。特殊支援另列 ${window.ROSTER_META.supportCount} 个单位，包含预备岗位和重复支援形态，不作为相同数量的独立人物。</p><p>异格通过游戏关联表相连；阿米娅的升变保留在同一人物入口。主要 NPC 是 ${window.ROSTER_META.npcCount} 条选录，不声称穷尽每一个有名角色。人物纪事结合完整公开档案、晋升记录、干员密录与所列主线活动，优先说明可确认的先后和事件后果。早年空白、身份不明、传说、梦境、记忆程序及 IF 分支均按材料说明，不用虚构串起缺失阶段。地区篇章和人物纪事的资料时点分别列明。</p><p>数据版本：<a href="https://github.com/Kengxxiao/ArknightsGameData/tree/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel" target="_blank" rel="noopener noreferrer">公开镜像版本 63c7cec ↗</a>。<a href="roster-meta.json" target="_blank" rel="noopener noreferrer">名录计数与本地快照摘要 ↗</a>。<a href="biography-meta.json" target="_blank" rel="noopener noreferrer">人物纪事覆盖与正文统计 ↗</a>。<a href="region-meta.json" target="_blank" rel="noopener noreferrer">地区分期与引用统计 ↗</a>。<a href="art-meta.json" target="_blank" rel="noopener noreferrer">图片范围与出处 ↗</a>。</p><p>干员档案已覆盖 ${window.OPERATOR_PROFILES.meta.records} 个干员入口、${window.OPERATOR_PROFILES.meta.variants} 份形态档案，整理种族、生日、身高、战斗经验、源石技艺及公开体检字段。年龄以本形态基础档案为准；未列明时标为未公开。<a href="profile-meta.json" target="_blank" rel="noopener noreferrer">干员档案范围与来源快照 ↗</a>。</p><p>《明日方舟》及相关角色、世界观、剧情的权利归鹰角网络等原权利人所有。请以游戏内原文与官方资料为准。</p></section></div></div></div>`;}
 function sourceNotes(s){if(s.chronicle)return window.REGION_UI.sourceNotes(s);let links=s.groups.map(g=>{const c=window.CHAPTER_INDEX?.[g];if(!c)return '';return `<li><a href="https://terra-library.pages.dev/" target="_blank" rel="noopener noreferrer">${esc(c.title)}</a> · ${esc(c.category)}${c.checked.length?`<br>已抽查：${c.checked.map(x=>esc(x.tag+'《'+x.title+'》')).join('；')}`:'<br>已核对目录；本卷未逐关校勘全文。'}</li>`;}).join('');links+=(s.extraSources||[]).map(([t,u])=>`<li><a href="${u}" target="_blank" rel="noopener noreferrer">${t} ↗</a> · 玩家维护的官方档案转录</li>`).join('');if(s.region==='columbia') links+='<li><a href="https://ak.hypergryph.com/special/4th-anniversary/index.html" target="_blank" rel="noopener noreferrer">鹰角官方《孤星》专题 ↗</a> · 活动引言与角色信息</li>';return `<details class="source-details" id="story-sources"><summary>本篇出处与延伸阅读</summary><p>采用范围：${s.scope}</p><ul>${links}</ul><p class="source-caution">泰拉文库没有可核实的章节直达链接。请打开站点目录，按篇名及以上关卡号定位；“已抽查”不代表已逐句比对整部作品。各篇的主题关联为编者解读。<a href="#/sources">查看完整编写说明 ↗</a></p></details>`;}
 function storyPage(s){
  const r=region(s.region),index=D.stories.indexOf(s),related=D.stories.filter(x=>x.region===s.region&&x.id!==s.id),fav=favorites.includes(s.id),p=progress[s.id];
  return `<div class="reading-progress" aria-hidden="true"><span id="progress-bar"></span></div><div class="book-top"><div class="crumb"><a href="#/atlas">大地诸境</a><span>/</span><a href="#/atlas/${r.id}">${r.name}</a><span>/</span><span>${s.label} ${num(s.order)}</span></div><div class="reading-tools"><button data-action="toggle-full" class="${prefs.full?'selected':''}" aria-pressed="${prefs.full}">${prefs.full?'完整阅读 · 含剧透':'低剧透导览'}</button><button data-action="smaller" aria-label="减小正文字号" ${prefs.size<=16?'disabled':''}>A−</button><button data-action="larger" aria-label="增大正文字号" ${prefs.size>=24?'disabled':''}>A＋</button><button data-action="favorite" data-id="${s.id}" aria-pressed="${fav}">${fav?'已收藏 ✓':'收藏此篇'}</button></div></div><div class="reader-layout"><aside class="reader-aside reader-left"><div class="eyebrow">IN THIS CHAPTER</div><a href="#book-start" data-anchor="book-start">篇首 · ${s.subtitle}</a>${prefs.full?window.ORIGIN_UI.toc(s):''}${prefs.full&&window.STORY_IMAGE_UI.items(s).length?`<a href="#story-cg-gallery" data-anchor="story-cg-gallery">剧情图册 · ${window.STORY_IMAGE_UI.items(s).length} 张</a>`:''}<a href="#cast" data-anchor="cast">相关人物纪事</a><a href="#/map/${s.region}">返回地区地图 ↗</a><a href="#story-sources" data-anchor="story-sources">出处与延伸阅读</a><div class="local-label">阅读状态</div><span id="reading-status">${p?.done?'已读完此篇':prefs.full?'阅读中':'低剧透导览'}</span><div class="local-label">${r.en}</div><p>${r.deck}</p>${related.length?'<div class="local-label">同地篇章</div>'+related.map(a=>`<a href="#/story/${a.id}">${a.title}</a>`).join(''):''}</aside><article class="book"><header class="book-head" id="book-start"><div class="eyebrow">${r.en} · ${s.label} ${num(s.order)}</div><h1>${s.title}</h1><div class="book-subtitle">${s.subtitle}</div><div class="book-meta"><span>原创叙事梳理</span><span>约 ${readTime(s)} 分钟</span><span>${r.theme}</span></div></header><div class="reading-scope"><strong>叙事范围</strong>　${s.scope}</div><div class="book-intro">${prefs.full?s.intro:s.modernIntro||s.intro}</div>${prefs.full?window.REGION_UI.body(s)+`<div class="reflection"><span>资料札记 / 时点与范围</span>${s.reflection}</div>`:`<div class="spoiler-gate"><div class="eyebrow">BEFORE YOU CONTINUE</div><h2>后面的故事，包含关键转折。</h2><p>你正在浏览低剧透导览。完整正文将讲述人物的选择、事件后果，部分篇章涉及角色死亡与剧情秘密。</p><button class="primary" data-action="enable-full">开启完整阅读 <span>→</span></button></div>`}${window.REGION_UI.cast(s,prefs.full)}${sourceNotes(s)}${prefs.full?`<div class="end-action"><button data-action="mark-done" data-id="${s.id}" aria-pressed="${!!p?.done}">${p?.done?'已读完此篇 ✓':'标记为已读'}</button></div>`:''}<nav class="next-chapters" aria-label="相邻篇章">${index>0?`<a href="#/story/${D.stories[index-1].id}"><small>← 上一篇 · ${region(D.stories[index-1].region).name}</small><strong>${D.stories[index-1].title}</strong></a>`:'<a href="#/home"><small>← 回到</small><strong>展卷首页</strong></a>'}${index<D.stories.length-1?`<a href="#/story/${D.stories[index+1].id}"><small>下一篇 · ${region(D.stories[index+1].region).name} →</small><strong>${D.stories[index+1].title}</strong></a>`:'<a href="#/routes"><small>继续旅程 →</small><strong>选择另一条阅读路线</strong></a>'}</nav></article><aside class="reader-aside reader-right"><div class="theme-motif" aria-hidden="true">${r.glyph}</div><div class="eyebrow">FIELD NOTES</div><p>以大地为卷<br>以众生为纪</p><p style="margin-top:25px;font-size:10px">本卷整理<br>2026.11.04</p><button data-action="share-story">复制本篇链接</button></aside></div>`;
 }
 function empty(t,d,action){return `<div class="empty"><h2>${t}</h2><p>${d}</p>${action?`<button data-action="${action}">重置筛选</button>`:'<a href="#/atlas">去大地诸境，翻开一篇故事 →</a>'}</div>`;}
 function shelf(){const saved=D.stories.filter(s=>favorites.includes(s.id));const reading=Object.entries(progress).filter(([id])=>story(id)).sort((a,b)=>(b[1].at||0)-(a[1].at||0)).map(([id])=>story(id));return `<div class="wrap">${pageHeading('YOUR READING ROOM','我的书架','把想读的故事留下，也记住已经走过的路。收藏与阅读记录仅保存在当前浏览器。','藏')}<section class="shelf-section"><h2>收藏的篇章 <span class="muted small">${saved.length}</span></h2><div class="catalogue">${saved.length?saved.map(catalogueRow).join(''):empty('书架还空着','在故事页点击“收藏此篇”，就能在这里再次找到它。')}</div></section><section class="shelf-section"><h2>最近阅读 <span class="muted small">${reading.length}</span></h2><div class="catalogue">${reading.length?reading.map(catalogueRow).join(''):empty('旅程即将开始','开启一篇故事的完整阅读后，这里会保留阅读记录。')}</div></section><p class="storage-note">${storageOK?'本地记录不会同步到其他设备。浏览器清理站点数据后，记录也会清除。':'当前浏览器限制了本地存储，记录仅在本次打开期间有效。'}</p></div>`;}
 function readRoute(){const parts=(location.hash.replace(/^#\/?/,'')||'home').split('/');return {view:parts[0],id:parts[1]||null,anchor:parts[2]||null};}
 function render({keepScroll=false}={}){
  const top=window.scrollY;const prev=current;current=readRoute();
  if(current.view==='atlas'&&lastRoute!==location.hash){filters={q:'',area:'all',region:region(current.id)?current.id:'all'};}
  if(current.view==='people'&&prev.view!=='people')filters={q:'',area:'all',region:'all'};
  const s=current.view==='story'?story(current.id):null;
  const views={home,map:()=>window.TERRA_MAP.render(current.id,prefs,progress),atlas,people,routes,sources,shelf};
  const character=current.view==='character'?R.recordPage(current.id,prefs):null;
  $('#main').innerHTML=s?storyPage(s):character?character:views[current.view]?views[current.view]():`<div class="wrap section">${empty('这一页没有收录','可以从全部篇章重新开始。')}</div>`;
  lastRoute=location.hash;document.body.classList.toggle('map-view',current.view==='map');if(current.view!=='map')document.body.classList.remove('map-expanded');if(current.view==='map')window.TERRA_MAP.activate();
  document.title=s?`${s.title} · 泰拉行纪`:character?`${R.index.get(current.id).name} · 泰拉行纪`:`${({home:'大地与众生',map:'大地行纪图',atlas:'大地诸境',people:'人物纪事',routes:'阅读路线',sources:'资料室',shelf:'我的书架'})[current.view]||'泰拉行纪'} · 泰拉行纪`;
  document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===current.view||(current.view==='story'&&a.dataset.nav==='atlas')||(current.view==='character'&&a.dataset.nav==='people');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  if(current.view==='atlas')drawCatalogue();if(current.view==='people')drawPeople();
  if(s&&prefs.full){progress[s.id]={...progress[s.id],at:Date.now()};save('progress',progress);}
  if(keepScroll)window.scrollTo({top,behavior:'instant'});else {window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
  if(!keepScroll&&!current.anchor&&s&&prefs.full&&(!s.origins||progress[s.id]?.originsRevision===window.REGIONAL_ORIGINS.meta.revision)&&progress[s.id]?.ratio>.04&&!progress[s.id]?.done){const savedRatio=progress[s.id].ratio;isRestoring=true;requestAnimationFrame(()=>{const a=$('.book');window.scrollTo({top:a.offsetTop+savedRatio*Math.max(1,a.offsetHeight-window.innerHeight),behavior:'instant'});isRestoring=false;updateProgress();});}
  if(current.anchor&&prefs.full)requestAnimationFrame(()=>{const target=document.getElementById(current.anchor);for(let el=target;el;el=el.parentElement)if(el.tagName==='DETAILS')el.open=true;target?.scrollIntoView({block:'start'});});
  updateProgress();
 }
 function updateProgress(){const bar=$('#progress-bar');if(!bar)return;const article=$('.book');const start=article.offsetTop;const available=article.offsetHeight-window.innerHeight;const ratio=Math.min(1,Math.max(0,(window.scrollY-start)/Math.max(1,available)));bar.style.width=(prefs.full?ratio*100:0)+'%';if(prefs.full&&!isRestoring&&current.view==='story'&&Date.now()-progressSavedAt>1200){progress[current.id]={...progress[current.id],previousEditionRatio:progress[current.id]?.previousEditionRatio??(progress[current.id]?.originsRevision!==window.REGIONAL_ORIGINS.meta.revision?progress[current.id]?.ratio:undefined),originsRevision:window.REGIONAL_ORIGINS.meta.revision,ratio,at:Date.now()};save('progress',progress);progressSavedAt=Date.now();}}
 function openPerson(id){const p=persons.find(x=>x.id===id);if(!p)return;const dialog=$('#person-dialog');dialog.innerHTML=`<div class="dialog-top"><div class="eyebrow">A LIFE IN TERRA</div><button class="text-btn" data-action="close-person" aria-label="关闭人物侧写">关闭 ×</button></div><div class="person-dialog-content"><div class="person-initial" aria-hidden="true">${esc(p.name[0])}</div><h2 id="person-title">${esc(p.name)}</h2><div class="meta">${region(p.region).name} · 人物侧写</div>${prefs.full?`<p class="role">${esc(p.role)}</p><p class="bio">${esc(p.bio)}</p>`:`<div class="spoiler-gate"><p>人物侧写包含对经历与选择的解读。开启完整阅读后可查看。</p><button class="primary" data-action="full-person" data-person-id="${p.id}">开启完整侧写 →</button></div>`}<div class="related">在这些篇章中继续认识这个人${R.byName(p.name)?`<a href="#/character/${R.byName(p.name).id}" data-close-dialog="person-dialog">${esc(R.byName(p.name).name)} · 人物纪事 ↗</a>`:''}${p.stories.map(id=>`<a href="#/story/${id}" data-close-dialog="person-dialog">${story(id).title} ↗</a>`).join('')}</div><p class="muted small" style="margin:20px 0 0">以关联篇章的时点为准；这是主题侧写，不是全部经历的最终结论。</p></div>`;if(!dialog.open)dialog.showModal();}
 function searchResults(q){const target=$('#search-results');q=q.trim();if(!q){target.innerHTML=`<div class="eyebrow">可以从这些名字开始</div><div class="route-steps" style="margin-top:18px">${['阿米娅','谢拉格','孤星','故乡','临光'].map(t=>`<button class="chip" data-query="${t}">${t}</button>`).join('')}</div>`;return;}const results=D.stories.filter(s=>matchesText(s,q));const characterResults=R.search(q,prefs);target.innerHTML=results.length||characterResults?results.map(s=>`<a class="search-result" href="#/story/${s.id}" data-close-dialog="search-dialog"><small>${region(s.region).name} / ${s.subtitle}</small><h3>${s.title}</h3><p>${prefs.full?s.intro:region(s.region).deck}</p></a>`).join('')+characterResults:`<p class="muted small">本卷没有找到“${esc(q)}”。可以尝试人物代号、地区或活动篇名。</p>`;}
 function openSearch(){searchReturnFocus=document.activeElement;$('#search-dialog').showModal();$('#global-search').value='';searchResults('');$('#global-search').focus();}
 function closeSearch(){$('#search-dialog').close();searchReturnFocus?.focus();}
 function toggleFavorite(id){if(favorites.includes(id))favorites=favorites.filter(x=>x!==id);else favorites.push(id);save('favorites',favorites);render({keepScroll:true});toast(favorites.includes(id)?'已放入我的书架':'已取消收藏');}
 document.addEventListener('click',async e=>{
  const area=e.target.closest('[data-area]');if(area){filters.area=area.dataset.area;document.querySelectorAll('[data-area]').forEach(b=>{b.classList.toggle('active',b===area);b.setAttribute('aria-pressed',b===area)});drawCatalogue();return;}
  const person=e.target.closest('[data-person]');if(person){openPerson(person.dataset.person);return;}
  const query=e.target.closest('[data-query]');if(query){$('#global-search').value=query.dataset.query;searchResults(query.dataset.query);return;}
  const anchor=e.target.closest('[data-anchor]');if(anchor){e.preventDefault();const t=document.getElementById(anchor.dataset.anchor);if(t){for(let el=t;el;el=el.parentElement)if(el.tagName==='DETAILS')el.open=true;t.scrollIntoView({behavior:'smooth',block:'start'});}else toast('开启完整阅读后可查看此节');return;}
  const closer=e.target.closest('[data-close-dialog]');if(closer){document.getElementById(closer.dataset.closeDialog)?.close();}
  const b=e.target.closest('[data-action]');if(!b)return;
  switch(b.dataset.action){
   case 'search':openSearch();break;
   case 'close-search':closeSearch();break;
   case 'close-person':$('#person-dialog').close();break;
   case 'theme':prefs.dark=!prefs.dark;applyPrefs();break;
   case 'toggle-full':prefs.full=!prefs.full;applyPrefs();render({keepScroll:true});toast(prefs.full?'已开启完整阅读，包含剧透':'已切换至低剧透导览');break;
   case 'enable-full':prefs.full=true;applyPrefs();render({keepScroll:true});requestAnimationFrame(()=>$('#part-0')?.scrollIntoView({behavior:'smooth',block:'start'}));break;
   case 'full-person':prefs.full=true;applyPrefs();render({keepScroll:true});openPerson(b.dataset.personId);break;
   case 'smaller':case 'larger':prefs.size=Math.min(24,Math.max(16,prefs.size+(b.dataset.action==='larger'?1:-1)));applyPrefs();document.querySelector('[data-action="smaller"]').disabled=prefs.size<=16;document.querySelector('[data-action="larger"]').disabled=prefs.size>=24;break;
   case 'favorite':toggleFavorite(b.dataset.id);break;
   case 'mark-done':progress[b.dataset.id]={...progress[b.dataset.id],done:!progress[b.dataset.id]?.done,at:Date.now()};save('progress',progress);render({keepScroll:true});toast(progress[b.dataset.id].done?'这一篇，已经走过':'已取消已读标记');break;
   case 'reset-filters':filters={q:'',area:'all',region:'all'};render({keepScroll:true});break;
   case 'share-story':try{await navigator.clipboard.writeText(location.href);toast('本篇链接已复制');}catch{toast('可从浏览器地址栏复制本篇链接');}break;
  }
 });
 document.addEventListener('input',e=>{if(e.target.id==='filter-query'){filters.q=e.target.value;if(current.view==='atlas')drawCatalogue();else drawPeople();}if(e.target.id==='global-search')searchResults(e.target.value);});
 document.addEventListener('change',e=>{if(e.target.id==='filter-region'){filters.region=e.target.value;if(current.view==='atlas')drawCatalogue();else drawPeople();}});
 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#search-dialog').open)openSearch();}});
 for(const id of ['search-dialog','person-dialog']){document.getElementById(id).addEventListener('click',e=>{if(e.target===e.currentTarget){const box=e.currentTarget.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)e.currentTarget.close();}});}
 window.addEventListener('hashchange',()=>render());window.addEventListener('scroll',updateProgress,{passive:true});window.addEventListener('resize',updateProgress);
 R.configure({enableFull:()=>{prefs.full=true;applyPrefs();render({keepScroll:true});}});
 render();
})();
